const source = $('Read Source').all().map(x => x.json).filter(x => x.name);
const done = new Set([...$('Read Published').all(), ...$('Read Review').all()].map(x => x.json.record_key).filter(Boolean));
let mode = 'daily';
try { const manual=$('Manual Mode').all(); if(manual.length) mode='manual'; } catch (e) {}
const rows = source.map((s, i) => {
  const key = String(s.profile_url || s.sunbiz_document_number || [s.name,s.street,s.city_state_zip].join('|')).trim();
  return { ...s, record_key:key, source_row:Number(s.row_number || i+2) };
}).filter(s => s.record_key && (mode === 'manual' ? String(s.c360_refresh_request || '').trim().toUpperCase() === 'REFRESH' : !done.has(s.record_key)));
return rows.slice(0, 100).map(json => ({json}));

const input=$input.all();
const groups=new Map();
const clean=(v)=>String(v?.html??v?.body??v?.data??(typeof v==='string'?v:'')).replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/\s+/g,' ').trim().slice(0,9000);
for(let i=0;i<input.length;i++){
 let source={},chamber={},website={},search={},contact={};
 try {source=$('Select Records').itemMatching(i).json;} catch(e) {source=$('Select Records').all()[i]?.json||{};}
 try {chamber=$('Fetch Chamber').itemMatching(i).json;} catch(e) {}
 try {website=$('Fetch Website').itemMatching(i).json;} catch(e) {}
 try {search=$('Search Public Web').itemMatching(i).json.body??$('Search Public Web').itemMatching(i).json;} catch(e) {}
 try {contact=$('Apify Contact Scraper').itemMatching(i).json;} catch(e) {}
 const key=source.record_key||String(i);
 if(!groups.has(key)) groups.set(key,{source,chamber_text:clean(chamber),website_text:clean(website),search_results:(search.organic_results||[]).slice(0,10).map(r=>({title:r.title,snippet:r.snippet,link:r.link})),contact_details:contact,linkedin_people:[],source_anomalies:[]});
 const raw=input[i].json; const people=Array.isArray(raw)?raw:Array.isArray(raw.body)?raw.body:Array.isArray(raw.items)?raw.items:[raw];
 for(const person of people) if(person && typeof person==='object' && (person.fullName||person.name||person.profileUrl||person.linkedinUrl)) groups.get(key).linkedin_people.push(person);
}
return [...groups.values()].map(v=>{v.linkedin_people=v.linkedin_people.slice(0,3);const filed=String(v.source.sunbiz_date_filed||'');if(/20[2-9][0-9]/.test(filed)&&new Date(filed).getTime()>Date.now())v.source_anomalies.push('Sunbiz filing date appears in the future; do not infer age from it');return {json:v};});

const contexts = $('Build Research Context').all().map(x => x.json);
const outputs = $input.all();
const out = [];
for (let i=0;i<outputs.length;i++) {
  const src = contexts[i]?.source || {};
  let p = outputs[i].json.output ?? outputs[i].json.text ?? outputs[i].json;
  if (typeof p === 'string') { try { p=JSON.parse(p.replace(/^\s*```(?:json)?/i,'').replace(/```\s*$/,'').trim()); } catch(e) { p={parse_error:String(e),people:[],evidence:[]}; } }
  if (!p || typeof p !== 'object') p={parse_error:'No structured output',people:[],evidence:[]};
  const people = (Array.isArray(p.people)?p.people:[]).filter(x=>x&&String(x.name||'').trim().split(/\s+/).length>=2).slice(0,3);
  p.people=people;
  const rawSite=String(p.website||src.website||'');
  let domain='';
  domain=rawSite.toLowerCase().replace(/^https?:\/\//,'').split('/')[0].split(':')[0].replace(/^www\./,'');
  if (!domain || !domain.includes('.') || domain.includes('linkedin.com') || domain.includes('facebook.com')) domain='';
  const known=people.map(x=>String(x.public_email||'').toLowerCase()).find(x=>x.endsWith('@'+domain));
  let pattern='';
  if (known) {
    const owner=people.find(x=>String(x.public_email||'').toLowerCase()===known);
    const parts=String(owner?.name||'').toLowerCase().replace(/[^a-z\s-]/g,'').split(/\s+/).filter(Boolean);
    const first=parts[0]||'', last=parts.at(-1)||'', local=known.split('@')[0];
    if(local===first+'.'+last) pattern='first.last'; else if(local===first[0]+last) pattern='flast'; else if(local===first) pattern='first'; else if(local===first+last) pattern='firstlast';
  }
  for (let j=0;j<people.length;j++) {
    const person=people[j];
    const parts=String(person.name).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z\s-]/g,'').split(/\s+/).filter(Boolean);
    const first=parts[0]||'', last=parts.at(-1)||'';
    if(!domain || !first || !last) continue;
    const local={ 'first.last':first+'.'+last, flast:first[0]+last, first:first, firstlast:first+last };
    const variants=[String(person.public_email||'').toLowerCase(),pattern?local[pattern]+'@'+domain:'',first+'.'+last+'@'+domain,first[0]+last+'@'+domain,first+'@'+domain,first+last+'@'+domain,first+'_'+last+'@'+domain,last+'@'+domain];
    const emails=[...new Set(variants.filter(x=>/^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(x)&&x.endsWith('@'+domain)))].slice(0,4);
    if(emails.length<4) continue;
    emails.forEach((email,k)=>out.push({json:{record_key:src.record_key,source:src,profile:p,person_index:j,candidate_email:email,candidate_rank:k+1,known_pattern:pattern,skip_check:false}}));
  }
  if(!out.some(x=>x.json.record_key===src.record_key)) out.push({json:{record_key:src.record_key,source:src,profile:p,candidate_email:'',skip_check:true}});
}
return out;

const candidate = $('Generate Candidates').item.json;
const result = $json.body ?? $json;
return {json:{...candidate,reacher:result}};

const groups=new Map();
for(const x of $input.all()) { const v=x.json; const key=v.record_key; if(!groups.has(key))groups.set(key,{source:v.source,profile:v.profile,checks:[]}); const g=groups.get(key); g.checks.push({person_index:v.person_index,person:g.profile.people?.[v.person_index]?.name||'',email:v.candidate_email,rank:v.candidate_rank,status:String(v.reacher?.is_reachable||'unknown').toLowerCase(),result:v.reacher}); }
const rows=[];
for(const item of groups.values()) { const src = item.source || {}; const p = item.profile || {};
const people=Array.isArray(p.people)?p.people:[];
const checks=item.checks||[];
const safe=checks.filter(c=>c.status==='safe').map(c=>c.email);
const confirmed=p.confirmed_match===true && String(p.company_match_confidence||'').toLowerCase()==='high';
const evidence=(Array.isArray(p.evidence)?p.evidence:[]).filter(e=>e&&/^https?:\/\//.test(e.url||''));
const complete=people.length>0 && people.every((person,i)=>new Set(checks.filter(c=>c.person_index===i).map(c=>c.email)).size>=4);
const high=confirmed && complete && safe.length>0 && evidence.length>0 && !p.parse_error;
const reasons=[];
if(!confirmed) reasons.push('Business identity not confirmed at high confidence');
if(!people.length) reasons.push('No attributable person found');
if(!complete) reasons.push('Fewer than four Reacher checks for at least one person');
if(!safe.length) reasons.push('No safe Reacher email');
if(!evidence.length) reasons.push('No cited source evidence');
if(p.parse_error) reasons.push('Research output could not be parsed');
const row={record_key:src.record_key,source_row:src.source_row,business_name:src.name||'',legal_name:src.sunbiz_legal_name||'',entity_status:src.sunbiz_status||'',category:src.category||'',street:src.street||'',city_state_zip:src.city_state_zip||'',website:p.website||src.website||'',chamber_profile:src.profile_url||'',business_phone:p.business_phone||src.phone||'',business_email:p.business_email||'',people_json:JSON.stringify(people),decision_makers:people.filter(x=>/owner|founder|president|ceo|manager|director|principal/i.test(x.role||'')).map(x=>x.name+' ('+x.role+')').join('; '),safe_email_addresses:safe.join('; '),email_checks_json:JSON.stringify(checks),observed_needs:JSON.stringify(p.observed_needs||[]),hypothesized_needs:JSON.stringify(p.hypothesized_needs||[]),automation_fit:p.automation_fit||'unknown',fit_reason:p.fit_reason||'',company_match_confidence:p.company_match_confidence||'low',profile_confidence:high?'high':'low',evidence_json:JSON.stringify({sources:[src.profile_url,src.website,src.sunbiz_source].filter(Boolean),claims:evidence,source_anomalies:p.source_anomalies||[]}),review_reason:reasons.join('; '),researched_at:new Date().toISOString(),review_status:high?'AUTO_PUBLISHED':'PENDING'};
rows.push({json:row}); }
return rows;

